 public static function url() { return admin_url( 'admin.php?page=wcj-pricing-discount-tasks' ); }
 public static function allowed( $module ) { $core = WCJ_Job_Store::core(); return WCJ_Task_Finder::allowed( $module ) && $core && isset( $core->all_modules[ $module ] ); }
 private static function link( $url, $label ) { return '<a href="' . esc_url( $url ) . '" target="_blank" rel="noopener noreferrer">' . esc_html( $label . ' (new tab)' ) . '</a>'; }
 private static function routes( $g ) {
  $binding = $g['native_by_edition'][ WCJ_Global_Discount_Job::edition() ];
  if ( ! $binding['applicable'] ) { return 'These controls are not included in this edition. Existing edition rights are unchanged.'; }
  $links = array();
  foreach ( $binding['urls'] as $url ) {
   // An editor template is not an existing product. Never fabricate a product ID.
   if ( false !== strpos( $url, '{' ) ) { continue; }
   $label = 0 === strpos( $url, 'edit.php?' ) ? 'Choose an existing product' : 'Full settings: ' . $g['label'];
   $links[] = self::link( admin_url( $url ), $label );
  }
  return implode( ' | ', array_unique( $links ) );
 }
 public static function render( $module = '', $selected = array() ) {
  $groups = array_filter( self::groups(), static function ( $g ) use ( $module, $selected ) { return ( ! $module || $module === $g['module'] ) && ( ! $selected || in_array( $g['group'], $selected, true ) ) && self::allowed( $g['module'] ); } );
  if ( ! $groups ) { return; }
  echo '<details class="wcj-pricing-groups"><summary>Pricing: settings and help</summary><p>Help and full settings open separately, keeping unsaved edits here. Available controls depend on your edition, module settings and product type. Opening help does not change prices, send requests or approve coupons.</p><ul>';
  foreach ( $groups as $g ) {
   echo '<li class="wcj-pricing-group" data-pricing-group="' . esc_attr( $g['group'] ) . '"><h4>' . esc_html( $g['label'] ) . '</h4><p>' . esc_html( $g['consequence'] ) . '</p>';
   if ( $g['context'] ) { echo '<p>' . esc_html( $g['context'] ) . '</p>'; }
   echo '<p>' . esc_html( wcj_is_module_enabled( $g['module'] ) ? 'Module on. Product and rule conditions still apply.' : 'Module off. Opening this help does not activate saved settings.' ) . '</p><p>' . self::routes( $g ) . ' | ' . self::link( $g['guide'], 'Help: ' . $g['label'] ) . '</p></li>';
  }
  echo '</ul></details>';
 }
 public static function entry() { if ( current_user_can( 'manage_woocommerce' ) ) { echo '<p><a href="' . esc_url( self::url() ) . '">Prices and discounts: choose an outcome</a></p>'; } }
 public static function register() { if ( current_user_can( 'manage_woocommerce' ) ) { add_submenu_page( 'woocommerce', 'Prices and discounts', 'Pricing choices', 'manage_woocommerce', 'wcj-pricing-discount-tasks', array( __CLASS__, 'hub' ) ); } }
 public static function hub() {
  if ( ! current_user_can( 'manage_woocommerce' ) ) { wp_die( 'Ask an administrator for access.', '', array( 'response' => 403 ) ); }
  wp_enqueue_style( 'wcj-global-discount-job', wcj_plugin_url() . '/assets/css/admin/wcj-global-discount-job.css', array(), '1.0' );
  $families = array(
   'automatic' => array( 'Automatic price rules', 'Change selling prices with existing rules. Product scope, rule order and other adjustments matter; a saved rule is not a final cart quote.', array( 'global_discount' => 'Global Discount', 'wholesale_price' => 'Wholesale Price', 'price_by_user_role' => 'Price by User Role', 'product_price_by_formula' => 'Product Price by Formula' ) ),
   'customer' => array( 'Customer-set or negotiated prices', 'Open Pricing uses the shopper amount as a price. Offer Price records a request. Best Price approval creates a one-use coupon and sends email; requesting alone does not change the selling price.', array( 'product_open_pricing' => 'Product Open Pricing', 'offer_price' => 'Offer Your Price', 'best_price' => 'Best Price' ) ),
   'shown' => array( 'Shown prices and extra charges', 'MSRP is a reference, not the selling price. Call for Price can remove actual prices and affect buying. Product Extra Fees adds real charges to the cart.', array( 'product_msrp' => 'MSRP', 'call_for_price' => 'Call for Price', 'product_extra_fees' => 'Product Extra Fees' ) )
  );
  echo '<div class="wrap wcj-pricing-hub"><h1>Prices and discounts</h1><p>Choose the outcome, then review its scope before changing a setting. No price, request, coupon or formula is changed or calculated by opening this page.</p><nav aria-label="Pricing outcomes">';
  foreach ( $families as $id => $f ) { echo '<a href="#pricing-' . esc_attr( $id ) . '">' . esc_html( $f[0] ) . '</a> '; } echo '</nav>';
  foreach ( $families as $id => $f ) {
   echo '<section class="wcj-pricing-family" id="pricing-' . esc_attr( $id ) . '"><h2>' . esc_html( $f[0] ) . '</h2><p>' . esc_html( $f[1] ) . '</p>';
   if ( 'automatic' === $id && self::allowed( 'global_discount' ) ) { echo '<p>' . self::link( WCJ_Global_Discount_Job::url(), 'Adjust an existing percentage discount' ) . '</p><p>This changes a real price rule, only when the module and group are on. Free and Plus: group 1 shortcut. Elite: eligible existing groups. Plus keeps all its native groups in full settings.</p>'; }
   foreach ( $f[2] as $module => $label ) {
    echo '<div class="wcj-pricing-module"><h3>' . esc_html( $label ) . '</h3>';
    if ( self::allowed( $module ) ) { echo '<p class="wcj-pricing-module-state" data-pricing-module-state="' . esc_attr( $module ) . '">' . esc_html( ucfirst( WCJ_Global_Discount_Job::edition() ) . ': Module ' . ( wcj_is_module_enabled( $module ) ? 'On' : 'Off' ) ) . '</p>'; self::render( $module ); }
    elseif ( ( 'best_price' === $module && 'elite' !== WCJ_Global_Discount_Job::edition() ) || ( 'product_extra_fees' === $module && 'free' === WCJ_Global_Discount_Job::edition() ) ) { echo '<p>' . esc_html( 'best_price' === $module ? 'Best Price is included in Elite. No native editor is offered in this edition.' : 'Product Extra Fees is included in Plus and Elite. No native editor is offered in Free.' ) . '</p>'; }
    else { echo '<p>Ask an administrator for access to this module.</p>'; } echo '</div>';
   }
   echo '</section>';
  }
  echo '</div>';
 }
 /** Add read-only assistance next to the existing product editors; never load a product price. */
 public static function product_boxes( $type, $post ) {
  if ( ! current_user_can( 'manage_woocommerce' ) || ! is_object( $post ) || ! current_user_can( 'edit_post', $post->ID ) ) { return; }
  if ( 'product' === $type ) { add_meta_box( 'wcj-pricing-help', 'Pricing settings: help and consequences', array( __CLASS__, 'product_help' ), 'product', 'normal', 'low' ); }
  elseif ( in_array( $type, array( 'post', 'page' ), true ) && self::allowed( 'wholesale_price' ) && ( false !== strpos( (string) $post->post_content, '[wcj_wholesale_price_table' ) || false !== strpos( (string) $post->post_content, '[wcj_product_wholesale_price_table' ) ) ) { add_meta_box( 'wcj-wholesale-table-help', 'Wholesale table help', array( __CLASS__, 'shortcode_help' ), $type, 'side', 'low' ); }
 }
 public static function product_help( $post ) {
  if ( ! current_user_can( 'manage_woocommerce' ) || ! current_user_can( 'edit_post', $post->ID ) ) { return; }
  echo '<p>These links explain the available pricing editors. An explanation does not mean a conditional field is enabled for this product. Keep formula expressions in their expert editor; this help never calculates them.</p>';
  self::render( '', array( 'best-history', 'offer-history', 'offer-product', 'role-product-enabled', 'role-product-values', 'msrp-product', 'open-product', 'formula-product', 'wholesale-product-tiers', 'wholesale-display' ) );
 }
 public static function variation_help() { self::render( '', array( 'role-product-values', 'msrp-product' ) ); }
 public static function shortcode_help() { self::render( 'wholesale_price', array( 'wholesale-display' ) ); }
 public static function category_help() { self::term_help( 'role-categories' ); }
 public static function tag_help() { self::term_help( 'role-tags' ); }
 private static function term_help( $group ) { if ( self::allowed( 'price_by_user_role' ) ) { echo '<tr><th>Role price help</th><td>'; self::render( 'price_by_user_role', array( $group ) ); echo '</td></tr>'; } }
}
add_action( 'admin_menu', array( 'WCJ_Pricing_Discount_Groups', 'register' ), 99 );
add_action( 'add_meta_boxes', array( 'WCJ_Pricing_Discount_Groups', 'product_boxes' ), 40, 2 );
add_action( 'woocommerce_variation_options_pricing', array( 'WCJ_Pricing_Discount_Groups', 'variation_help' ), 40 );
add_action( 'product_cat_edit_form_fields', array( 'WCJ_Pricing_Discount_Groups', 'category_help' ), 40 );
add_action( 'product_tag_edit_form_fields', array( 'WCJ_Pricing_Discount_Groups', 'tag_help' ), 40 );
